Translate("frFR", "city-of-dalaran", {
	title = "Cité de Dalaran",
	aliases = { "Dalaran-la-cité", "la cité des magi" },
	sections = {
		{
			title = "Résumé",
			text = [=[La cité de {link:dalaran}Dalaran{/link} se dresse de nouveau sur la rive ouest du {red:lordamere-lake}Lac Lordamere{/red}, au pied des {link:alterac-mountains}montagnes d'Alterac{/link}. Ses flèches violettes s'élèvent au-dessus de murs neufs et de rues lumineuses, ses banques et ses auberges sont ouvertes, et ses magi marchent de nouveau parmi les marchands, les artisans et les hôtes venus de terres lointaines. Pendant des années, la cité s'est cachée derrière un grand dôme de lumière tandis que ses sorciers la rebâtissaient. Cette barrière est tombée. Le monde peut de nouveau voir Dalaran, et Dalaran doit à présent répondre au monde.]=],
		},
		{
			title = "Origines",
			text = [=[L'histoire de {link:dalaran}Dalaran{/link}, première des cités libres d'{link:arathor}Arathor{/link} et foyer du {link:kirin-tor}Kirin Tor{/link}, est racontée dans sa propre chronique. Durant la {link:third-war}Troisième Guerre{/link}, le {link:scourge}Fléau{/link} vint à ses portes et prit le grimoire de {link:medivh}Medivh{/link}, et {link:archimonde}Archimonde{/link} brisa la cité d'un seul sort. Les magi survivants revinrent dans les ruines. Ils élevèrent un immense dôme magique au-dessus du cœur de leur cité, et derrière lui ils se mirent à l'ouvrage. À l'extérieur, les patrouilles des {link:the-wizards-of-ambermill}sorciers de Dalaran{/link} et leurs élémentaires asservis gardaient les faubourgs en ruine, et rares étaient ceux qui, s'approchant, y étaient les bienvenus.]=],
		},
		{
			title = "Le temps présent",
			text = [=[L'ouvrage est achevé, ou presque. Nul hors du {link:kirin-tor}Kirin Tor{/link} ne peut encore dire pourquoi la barrière est tombée. La cité est ouverte, mais elle n'est pas en paix. Des enchantements s'égarent, des créations arcaniques se libèrent de leurs liens, et une énergie démoniaque a été ressentie dans ses rues. Des enquêteurs du Kirin Tor parlent à voix basse d'un trouble qui s'aggrave de jour en jour, et ils ont reçu l'ordre de garder les citoyens au calme. Le Kirin Tor se compte désormais parmi les nations de l'{link:alliance}Alliance{/link}. La {link:horde}Horde{/link} n'est pas la bienvenue ici, et les gardes de la cité traitent ses membres en ennemis. De nouveaux amis sont venus à la place : le {link:high-order}High Order{/link} des {link:skyborne}Skyborne{/link}, dont les navires fendeurs de ciel voguent entre {link:dalaran}Dalaran{/link} et {link:zephras-isle}Zephras Isle{/link} à travers les plans.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Le {link:kirin-tor}Kirin Tor{/link}.{/b} Archimages, archivistes, arcanistes et enquêteurs, les maîtres de la cité.
• {b}Les gardes de {link:dalaran}Dalaran{/link}.{/b} Gardes et exécuteurs du Kirin Tor, et sentinelles arcaniques qui veillent d'elles-mêmes.
• {b}Citoyens et marchands.{/b} Banquiers, aubergistes, forgerons, tailleurs, joailliers et un fabricant de jouets, ainsi qu'un orphelinat et sa matrone.
• {b}Les {link:skyborne}Skyborne{/link}.{/b} Des mages du {link:high-order}High Order{/link}, qui arrivent au quai des fendeurs de ciel de la cité.
• {b}Les visiteurs.{/b} Parmi eux, un maître des druides et un Bien-né venu de loin.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La fondation.{/b} {link:dalaran}Dalaran{/link} fut la première cité d'{link:arathor}Arathor{/link} à se gouverner elle-même, et ses magi fondèrent le {link:kirin-tor}Kirin Tor{/link}.
• {b}La chute.{/b} Durant la {link:third-war}Troisième Guerre{/link}, la cité fut détruite.
• {b}La barrière.{/b} Les magi rebâtirent Dalaran derrière un dôme qui tenait le monde à l'écart.
• {b}Le temps présent.{/b} La barrière a disparu, et la cité a ouvert ses portes à ses alliés.]=],
		},
		{
			title = "Légendes de la cité",
			text = [=[• Des {link:the-wizards-of-ambermill}sorciers de Dalaran{/link} surveillent désormais les routes du nord. Dans la {link:silverpine-forest}Forêt des Pins argentés{/link}, ils disent le faire depuis que la barrière est tombée.
• L'archimage {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} écrivit jadis un ouvrage sur les légendes des trolls Gurubashi. Sa fille, à son grand chagrin, devint pirate.
• Le {link:kirin-tor}Kirin Tor{/link} entretient un portail pour le {link:high-order}High Order{/link}, afin que ses jeunes mages puissent rejoindre {link:stormwind-city}Stormwind{/link} et y rencontrer le régent.]=],
		},
	},
})

Translate("frFR", "the-eventide", {
	title = "The Eventide",
	aliases = { "Eventide" },
	sections = {
		{
			title = "Résumé",
			text = [=[The Eventide est l'un des quartiers de la cité rebâtie de {link:dalaran}Dalaran{/link}. Comme le reste de la cité, il fut élevé à neuf derrière la grande barrière tandis que le monde extérieur ne pouvait le voir, et il n'a été ouvert aux visiteurs que depuis peu. Ses rues sont neuves, et bien des gens qui les parcourent le sont aussi. Nulle chronique ne rapporte encore qui demeure dans l'Eventide, ni ce que les magi y bâtirent en premier. Ceux qui arpentent ses rues découvrent une cité fière de sa restauration, et plus inquiète qu'elle ne voudrait l'admettre.]=],
		},
	},
})

Translate("frFR", "archmage-ansirem-runeweaver", {
	title = "Archimage Ansirem Runeweaver",
	subtitle = "Archimage du Kirin Tor",
	found = "La cité de Dalaran",
	hint = [=[Cherchez l'archimage du Kirin Tor dont le savoir s'étend de Strangleronce jusqu'aux cieux.]=],
	allegiance = "Kirin Tor",
	aliases = { "Ansirem Runeweaver", "Ansirem" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'archimage Ansirem Runeweaver est l'un des grands magi du {link:kirin-tor}Kirin Tor{/link}. Il a œuvré tout au long de la longue reconstruction de {link:dalaran}Dalaran{/link}, et son savoir est immense. Il y a des années, il écrivit un ouvrage sur les légendes de l'empire Gurubashi, et il en sait plus sur les reliques trolls de {link:stranglethorn-vale}Strangleronce{/link} que tout autre érudit du nord. Il est aussi père, et sa fille unique lui a brisé le cœur de la plus singulière des façons : elle s'est enfuie à {link:booty-bay}Baie-du-Butin{/link} pour devenir pirate.]=],
		},
		{
			title = "Importance",
			text = [=[Ansirem est le visage du {link:kirin-tor}Kirin Tor{/link} pour le monde au-delà de ses murs. Il répond aux questions des princes comme des pirates. Quand les {link:skyborne}Skyborne{/link} de {link:zephras-isle}Zephras Isle{/link} furent menacés par le culte du Seigneur des vents, c'est Ansirem qui vint avec les mages du Kirin Tor se tenir à leurs côtés. Leur amitié est désormais l'alliance de son ordre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie la malédiction de la Pierre des marées pour les gobelins de {link:booty-bay}Baie-du-Butin{/link}.
• Il trouva une dague troll à {link:stranglethorn-vale}Strangleronce{/link} et la donna à sa fille rebelle, {link:catelyn-the-blade}Catelyn{/link}.
• Il vint sur {link:zephras-isle}Zephras Isle{/link} avec le {link:kirin-tor}Kirin Tor{/link} et rencontra le magistère suprême du {link:high-order}High Order{/link}.
• Il envoie les jeunes druides des {link:skyborne}Skyborne{/link} au {link:cenarion-circle}Cercle cénarien{/link}, afin qu'ils apprennent à sauver leur foyer.]=],
		},
	},
	chapters = {
		{
			title = "La Pierre des marées",
			hint = "Apportez à l'archimage une énigme magique de Strangleronce.",
			text = [=[Les brassards venaient d'élémentaires d'eau du lointain sud, et ils portaient les résidus d'une malédiction troll. Ansirem fut ravi. Il avait écrit sur la Pierre des marées il y a longtemps. Le mage qui détenait la Pierre, découvrit-il, amplifiait sa puissance au moyen d'un autel. On pouvait la surpasser avec la bonne relique, et il savait exactement laquelle : une ancienne dague troll. Il n'y avait qu'un problème. Il l'avait donnée à sa fille.]=],
		},
		{
			title = "Les enfants de la nature",
			hint = "Parlez à l'archimage en tant que jeune druide des cieux.",
			text = [=[Aux jeunes druides des {link:skyborne}Skyborne{/link}, Ansirem offre des conseils qu'ils n'attendaient pas d'un mage. Il existe sur {link:azeroth}Azeroth{/link} un ancien ordre de naturalistes, leur dit-il, et une {link:night-elves}elfe de la nuit{/link} à {link:stormwind-city}Stormwind{/link} peut leur montrer le chemin de sa place forte à {link:moonglade}Reflet-de-Lune{/link}. S'ils veulent sauver leur foyer, ils ont beaucoup à apprendre.]=],
		},
	},
	mentions = {
		{ text = "Analyse magique" },
		{ text = "La clé d'Ansirem" },
		{ text = "Enfant de la nature" },
		{
			text = [=[Affronter {link:high-priestess-lorthuna}Lorthuna{/link}, sur les flèches de {link:zephras-isle}Zephras{/link}]=],
		},
	},
	bonds = {
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "l'a rencontré sur les flèches" },
		{ id = "archmage-modera", name = "Archimage Modera", note = "une collègue archimage" },
		{ id = "denaaris-stargale", name = "Denaaris Stargale", note = "reçoit le High Order dans sa cité" },
	},
})

Translate("frFR", "archmage-modera", {
	title = "Archimage Modera",
	subtitle = "Archimage du Kirin Tor",
	found = "La cité de Dalaran",
	hint = [=[Cherchez la vieille archimage qui sert le Kirin Tor depuis la Deuxième Guerre.]=],
	allegiance = "Kirin Tor",
	aliases = { "Modera" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'archimage Modera est l'un des plus anciens membres du conseil qui gouverne le {link:kirin-tor}Kirin Tor{/link}. Elle siégeait parmi les magi qui dirigeaient {link:dalaran}Dalaran{/link} au temps de la {link:second-war}Deuxième Guerre{/link}. Avant la peste, elle s'éleva contre {link:kel-thuzad}Kel'Thuzad{/link} quand son étude de la nécromancie fut découverte, et avertit que ses méthodes les feraient tous condamner. Son avertissement fut entendu, et il fut chassé. Elle survécut à la chute de la cité et resta pour la voir renaître.]=],
		},
		{
			title = "Importance",
			text = [=[Modera est une mémoire vivante de l'ancien {link:kirin-tor}Kirin Tor{/link}, et une voix qui avait vu juste au sujet de l'homme qui détruisit {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'a encore été consigné de son rôle dans la reconstruction, ni de ce qu'elle pense de la chute de la barrière.]=],
		},
	},
	bonds = {
		{ id = "archmage-ansirem-runeweaver", name = "Archimage Ansirem Runeweaver", note = "un collègue archimage" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "elle s'est élevée contre lui" },
	},
})

Translate("frFR", "denaaris-stargale", {
	title = "Denaaris Stargale",
	subtitle = "Émissaire du High Order",
	found = "Le quai des fendeurs de ciel de Dalaran",
	hint = [=[Trouvez le mage du High Order qui accueille les nouveaux venus de Zephras Isle.]=],
	allegiance = "High Order · Skyborne",
	aliases = { "Danaaris Stargale", "Denaaris" },
	sections = {
		{
			title = "Résumé",
			text = [=[Denaaris Stargale est un mage du {link:high-order}High Order{/link} des {link:skyborne}Skyborne{/link}. Le magistère suprême voulait être le premier de son peuple à poser le pied sur {link:azeroth}Azeroth{/link}, mais les troubles de {link:zephras-isle}Zephras Isle{/link} le retinrent chez lui. Denaaris partit donc en avant. Il attend à {link:dalaran}Dalaran{/link} pour recevoir chaque jeune magistère qui descend des cieux.]=],
		},
		{
			title = "Importance",
			text = [=[Denaaris est le premier ami que les jeunes du {link:high-order}High Order{/link} rencontrent dans le monde d'en bas. Par lui, ils apprennent que le {link:kirin-tor}Kirin Tor{/link} appartient à une {link:alliance}Alliance{/link} de nations, et que son cœur se trouve à {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accueille à {link:dalaran}Dalaran{/link} les jeunes magistères du {link:high-order}High Order{/link}.
• Il les envoie par un portail du {link:kirin-tor}Kirin Tor{/link} rencontrer {link:bolvar-fordragon}Bolvar Fordragon{/link} à {link:stormwind-city}Stormwind{/link}.
• Il leur demande de revenir auprès du High Order de temps à autre, car il pourrait y avoir des tâches pour eux.]=],
		},
	},
	mentions = {
		{ text = "La cité magique de {link:dalaran}Dalaran{/link}" },
		{ text = "Bienvenue en {link:azeroth}Azeroth{/link}" },
	},
	bonds = {
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "le magistère suprême qu'il sert" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "le régent auprès duquel il les envoie" },
	},
})

Translate("frFR", "arcanist-laurain", {
	title = "Arcaniste Laurain",
	subtitle = "Gardienne du quai des fendeurs de ciel",
	found = "Le quai des fendeurs de ciel de Dalaran",
	hint = [=[Trouvez l'arcaniste qui annonce les arrivées et les départs du fendeur de ciel.]=],
	allegiance = "Kirin Tor",
	aliases = { "Laurain" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'arcaniste Laurain veille sur le quai où les navires fendeurs de ciel des {link:skyborne}Skyborne{/link} arrivent à {link:dalaran}Dalaran{/link}. Elle annonce chaque arrivée de {link:zephras-isle}Zephras Isle{/link} et prévient les voyageurs de faire attention en montant à bord. Le voyage entre les plans, avertit-elle, peut être agité, et il est sage de se tenir fermement à quelque chose.]=],
		},
		{
			title = "Importance",
			text = [=[Laurain se tient devant une porte qui n'existait pas il y a peu : une route entre {link:azeroth}Azeroth{/link} et les îles perdues du ciel.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle s'occupe du quai des fendeurs de ciel et des voyageurs qui y passent.]=],
		},
	},
	bonds = {
		{ id = "denaaris-stargale", name = "Denaaris Stargale", note = "reçoit les arrivants" },
	},
})

Translate("frFR", "investigator-kath-leen", {
	title = "Enquêtrice Kath'leen",
	subtitle = "Enquêtrice du Kirin Tor",
	found = "Un coin tranquille de Dalaran, avec l'enquêtrice Silva",
	hint = [=[Tendez l'oreille vers les deux enquêtrices qui parlent à voix basse dans les rues de Dalaran.]=],
	allegiance = "Kirin Tor",
	aliases = { "Kath'leen" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'enquêtrice Kath'leen se penche sur un trouble que les magi de {link:dalaran}Dalaran{/link} préféreraient garder pour eux. Un dérèglement a été ressenti dans la cité, et il n'a fait que gagner en gravité. Elle s'inquiète de ce qui arrivera si les citoyens n'en sont pas informés. Sa partenaire, l'enquêtrice {link:investigator-silva}Silva{/link}, lui rappelle leurs ordres.]=],
		},
		{
			title = "Importance",
			text = [=[L'inquiétude de Kath'leen est une fissure dans le visage calme de la cité. Quelque chose ne va pas à {link:dalaran}Dalaran{/link}, et ceux qui le savent ont reçu l'ordre de ne rien dire.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit encore ce qu'est ce dérèglement, ni qui a donné leurs ordres aux enquêtrices.]=],
		},
	},
	bonds = {
		{ id = "investigator-silva", name = "Enquêtrice Silva", note = "sa partenaire" },
	},
})

Translate("frFR", "investigator-silva", {
	title = "Enquêtrice Silva",
	subtitle = "Enquêtrice du Kirin Tor",
	found = "Un coin tranquille de Dalaran, avec l'enquêtrice Kath'leen",
	hint = [=[Tendez l'oreille vers les deux enquêtrices qui parlent à voix basse dans les rues de Dalaran.]=],
	allegiance = "Kirin Tor",
	aliases = { "Silva" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'enquêtrice Silva travaille aux côtés de l'enquêtrice {link:investigator-kath-leen}Kath'leen{/link} sur une affaire qui trouble le {link:kirin-tor}Kirin Tor{/link}. Toutes deux ont étudié des relevés pris sur un pylône, et Silva veut les réexaminer, au cas où quelque chose leur aurait échappé. Silva s'en tient aux ordres qu'elles ont reçus. Tant qu'elles n'en sont pas sûres, le silence est le meilleur moyen de garder la cité au calme.]=],
		},
		{
			title = "Importance",
			text = [=[Silva incarne la vieille habitude du secret du {link:kirin-tor}Kirin Tor{/link}. L'ordre a toujours placé son propre jugement au-dessus des craintes du commun.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit encore quel pylône elles ont étudié ni ce qu'elles ont trouvé.]=],
		},
	},
	bonds = {
		{ id = "investigator-kath-leen", name = "Enquêtrice Kath'leen", note = "sa partenaire" },
	},
})
